cat > /app/parse.py <<'EOF'
import re, collections
x=y=z=0.0; e=0.0; obj=-1
segs=collections.defaultdict(list)   # obj -> (x0,y0,z0,x1,y1,e)
zs=collections.defaultdict(set)
m486=[]  # (line, obj)
for ln,line in enumerate(open('/app/text.gcode',errors='replace'),1):
    line=line.strip()
    if line.startswith('M486'):
        m=re.match(r'M486 S(-?\d+)',line)
        if m: obj=int(m.group(1))
        continue
    if line.startswith(('G0','G1')) and 'X' in line or line.startswith(('G0','G1')):
        # tokenize
        d={}
        for tok in line.split()[1:]:
            if tok and tok[0] in 'XYZE':
                try: d[tok[0]]=float(tok[1:])
                except: pass
        nx=d.get('X',x); ny=d.get('Y',y); nz=d.get('Z',z); ne=d.get('E',0.0)
        extruding = ne>0.0001
        if extruding:
            segs[obj].append((x,y,z,nx,ny,nz,ne))
            zs[obj].add(round(z,3))
        x,y,z=nx,ny,nz
for o in segs:
    ss=segs[o]
    xs=[p for s in ss for p in (s[0],s[3])]; ys=[p for s in ss for p in (s[1],s[4])]
    print(o, 'segs',len(ss),'z',min(zs[o]),max(zs[o]),'layers',len(zs[o]),'x',min(xs),max(xs),'y',min(ys),max(ys))
    print('  zs sample', sorted(zs[o])[:10], '...', sorted(zs[o])[-10:])
EOF
python3 /app/parse.py
